export type PubKey = keyof typeof T;

export function usePubTx() {
  const lang = useAppLang();
  const i = ORDER.indexOf(lang);
  return (k: PubKey, v?: Record<string, string | number>) =>
    (T[k][i] || T[k][0]).replace(/\{(\w+)\}/g, (_, x) => String(v?.[x] ?? ""));
}
